# 1, +1 for an email, +1 when namesakeCount is 0, capped at 3. Runs after the namesake count is
# recorded and before the owner is persisted, so the level and the audit line reflect the final
# values.
assignMembershipLevel:
  class: org.springframework.samples.petclinic.rest.function.owner.AssignOwnerMembershipLevel
  govern: [ transaction ]
  next: assignBulkSignupWarning

